SourceCode.Declaration:
/// <summary>
/// Class to contain the origins of a collector. If a collector has an indication it originates from a field in the InventDim table, when there is an inventDim buffer in the context, the value from the InventDim Field could automatically be set for the collector.
/// </summary>
class TFMFieldOrigins
{
    Map tableFields;
    Set extendedDataTypes;
    TFMLogicBlockName originBlockName;
    str matchedSource;

}

Method.Source:
public TFMLogicBlockName parmOriginBlockName(TFMLogicBlockName _originBlockName = originBlockName)
{
    originBlockName = _originBlockName;
    return originBlockName;
}

protected void new()
{
    tableFields = new Map(Types::String, Types::Class);
    extendedDataTypes = new Set(Types::String);
}

public static TFMFieldOrigins Construct()
{
    return new TFMFieldOrigins();
}

public Set fieldsFromTable(TableName _tableName)
{
    return tableFields.exists(_tableName) ? tableFields.lookup(_tableName) : new Set(Types::String);
}

public void setMatchedSource(str _matchedSource, boolean _forceOverwrite = false)
{
    matchedSource = !matchedSource ? _matchedSource : (_forceOverwrite ? _matchedSource : matchedSource);

}

public void addTableField(TableName _tableName, FieldName _fieldName)
{
    Set fields = tableFields.exists(_tableName) ? tableFields.lookup(_tableName) : new Set(Types::String);
    fields.add(_fieldName);
    tableFields.insert(_tableName,fields);
}

public str originsString()
{
    str             ret = '';
    MapEnumerator   mEnum = tableFields.getEnumerator();
    Set             fields;
    SetEnumerator   sEnum;
    str             fieldsStr;

    ret = 'matchedSource:' + matchedSource;

    while (mEnum.moveNext())
    {
        fields = mEnum.currentValue();
        sEnum = fields.getEnumerator();
        fieldsStr = '';
        while (sEnum.moveNext())
        {
            fieldsStr += (fieldsStr ? ',' :'')+ sEnum.current();
        }
        ret += (ret ? TFMConstants::lineBreak() : '') + mEnum.currentKey() + ': ' + fieldsStr;
    }
    sEnum = extendedDataTypes.getEnumerator();
    while(sEnum.moveNext())
    {
        ret += (ret ? TFMConstants::lineBreak() : '') + sEnum.current();
    }

    return ret;
}

public Set fieldsAndEDTs()
{
    Set             ret = new Set (Types::String);
    MapEnumerator   mEnum = tableFields.getEnumerator();
    Set             fields;
    SetEnumerator   sEnum;
    str             fieldsStr;
    while (mEnum.moveNext())
    {
        fields = mEnum.currentValue();
        sEnum = fields.getEnumerator();
        fieldsStr = '';
        while (sEnum.moveNext())
        {
            ret.add(sEnum.current());
        }

    }
    sEnum = extendedDataTypes.getEnumerator();
    while(sEnum.moveNext())
    {
        ret.add(sEnum.current());
    }

    return ret;
}

public void mergeInOrigin(TFMFieldOrigins _origin)
{
    MapEnumerator mEnum = _origin.getTableFields().getEnumerator();
    Set fields;
    SetEnumerator sEnum;
    while (mEnum.moveNext())
    {
        fields = mEnum.currentValue();
        sEnum = fields.getEnumerator();
        while(sEnum.moveNext())
        {
            this.addTableField(mEnum.currentKey(), sEnum.current());
        }
    }
    sEnum = _origin.dataTypesEnumerator();
    while (sEnum.moveNext())
    {
        this.addExtendedDataType(sEnum.current());
    }
    this.setMatchedSource(_origin.matchedSource());
}
